head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > minByteLength]<br/>Textarea 컴포넌트의 최소 입력 바이트 길이를 설정합니다.",
    "validation" : [
        "최소 입력 바이트 길이를 양의 정수로 설정합니다.",
        "config.xml 의 WebSquare/byteCheckEncoding/@value 가 'euc-kr' 이면 한글 1자는 2바이트로 계산됩니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 최소 입력을 제한하지 않습니다.",
        "validate() 메소드 실행 시 입력값이 없거나 입력값의 Byte 수가 설정값보다 작으면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "validate() 시스템 기본 메시지는 'n byte 이상 입력해야 합니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "minlength 를 함께 설정한 경우 minlength 의 유효성 체크가 먼저 실행됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (minByteLength=10, '가나다라마'(10byte) 입력 → byte 수가 설정값 이상 → PASS)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2 (minByteLength=10, '가나'(4byte) 입력 → byte 수가 설정값 미만 → FAIL, 시스템 기본 메시지 '10byte 이상 입력해야 합니다.')
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


// target3 (minByteLength=10, 입력값 없음 → byte 수 0 < 10 → FAIL)
scwin.btn_validate3_onclick = function (e) {
    scwin.check_validate(target3);
}


// target4 (minByteLength 미설정 → -1 적용, 입력값 없어도 byte 체크 미수행 → mandatory/maxlength/minlength/maxByteLength 도 없으므로 validate 실행 조건 미충족 → 결과는 그대로 PASS 처리)
scwin.btn_validate4_onclick = function (e) {
    scwin.check_validate(target4);
}


// target5 (minByteLength=10, minlength=10 함께 설정, 한글 4자(8byte) 입력)
//   - 유효성 체크 순서: mandatory → maxlength → minlength → maxByteLength → minByteLength
//   - minlength=10 미달(4자) → minlength 단계에서 FAIL → '최소 10 자리 이상 입력해야 합니다.'
//   - 즉 minByteLength 보다 minlength 가 먼저 검사됨을 확인
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가나다라");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}


// target6 (minByteLength=10, displaymessage=true, invalidMessage 설정 → validate 실패 시 사용자 메시지 출력)
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("가나");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}


// target7 (minByteLength=10, displaymessage=true, invalidMessageFunc 설정 → 사용자 정의 함수 메시지 출력)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("가나");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}


// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidType = this.getType();
    let invalidValue = this.getValue();
    let msg = "Not valid.";

    if (invalidType === "minByteLength") {
        msg = "사용자 정의 메시지: 최소 " + invalidValue + " byte 미달";
    }
    return msg;
}
